import re

def slugify(text):
    return re.sub(r'[^a-z0-9]', '-', text.lower())

import unittest
from mod import slugify
class T(unittest.TestCase):
    def test_words(self):
        self.assertEqual(slugify('Hello World'), 'hello-world')
        self.assertEqual(slugify('a-b'), 'a-b')

if __name__ == '__main__':
    unittest.main()

